from vllm.v1.attention.backends.registry import AttentionBackendEnum, register_backend

@register_backend(AttentionBackendEnum.CUSTOM)
class MyBackend(AttentionBackend):
    supported_dtypes = [torch.float16, torch.bfloat16]
    supported_kv_cache_dtypes = ["auto", "float16", "bfloat16"]

    @staticmethod
    def get_name() -> str:
        return "CUSTOM"

    @staticmethod
    def get_impl_cls():
        return MyImpl          # per-layer forward()

    @staticmethod
    def get_builder_cls():
        return MyBuilder       # per-step build()

    @staticmethod
    def get_supported_kernel_block_sizes(kv_cache_spec=None):
        return [MultipleOf(16)]

    @classmethod
    def supports_compute_capability(cls, capability):
        return capability >= DeviceCapability(8, 0)

class MyBuilder(AttentionMetadataBuilder[MyMetadata]):
    _cudagraph_support = AttentionCGSupport.UNIFORM_SINGLE_TOKEN_DECODE
    reorder_batch_threshold = 1    # put decodes first

    def build(self, common_prefix_len, common_attn_metadata, fast_build=False):
        ...
